; ---------------------------------------------------------------------------
; Core B, ENG_RING -- a bank of six tuned two-pole resonators struck by a
; short noise burst. Generated by dspring.py; shares bdnoise.asm's LCG and the
; family's three coefficient curves, and carries its own copies of the knob
; trim and clamp (see zr08/zr09 at the foot of this file).
;
; ⚠️ CREDIT AND PROVENANCE. Jesse asked for "the rings algo" and linked
; pichenettes/eurorack. Mutable Instruments' Rings is MIT-licensed, (c) Emilie
; Gillet. THIS IS NOT A PORT OF IT. The sources could not be fetched in the
; session that wrote this -- GitHub is unreachable from that sandbox and it has
; no API access to the repository, and routing around a blocked fetch is not
; allowed -- and there is no Rings hardware or emulator in the container to
; capture reference audio from, so there was nothing to port from AND nothing
; to measure against. What is here is a modal resonator bank written from the
; published description of one. The claim is STRUCTURAL -- a mechanism none of
; the other five engines have -- never "within x% of a Rings".
;
;   LCG noise -> one-pole (BRITE) -> 2 ms envelope
;                                      |
;   6 x  y[n] = a1*y[n-1] + a2*y[n-2] + x[n]      a1 = 2r*cos(w), a2 = -r^2
;                                      |
;                       weighted sum (POS) -> guard envelope -> VCA
;
; ⚠️ THE FIRST VERSION OF THIS SOUNDED LIKE A BASS DRUM. Jesse, on flashing it
; (5 Oct 2026): "all the drums are great except for the rings emulator. It just
; sounds like a bass drum." He was right, and the fault was not in this file's
; arithmetic -- every gate passed and the engine landed where its constants
; asked. It was in WHAT the constants asked for: four partials spaced
; GEOMETRICALLY (a constant ratio, the one arrangement a struck object never
; has) with a decay taken straight from a curve fitted to drum envelopes.
; Four sparse overtones over a 400 ms fundamental IS a tom. dspring.py holds
; the three changes; the structural one is that STRUCTURE now blends between
; the harmonic series and a free bar's modes, so it sweeps between two real
; objects instead of stretching one.
;
; ⚠️ TWO-POLE DIRECT FORM, NOT THE FAMILY'S SVF, AND THE REASON IS cos(w). A
; resonator needs its decay and its pitch to be separate, which an SVF gives
; only by holding the Q fixed and enveloping the output (what the snare does).
; Here the POLE RADIUS is the decay -- that is what makes six partials ring for
; six different lengths, which is the whole sound of a struck object -- and
; that needs cos(w), which no table here holds. It falls out of the one that
; does: N_F is sin(pi*fc/SR) = sin(theta), w is 2*theta, and
; cos(2*theta) = 1 - 2*sin^2(theta). One multiply, one shift, one subtract, no
; new table and no X words to find.
; ---------------------------------------------------------------------------
zr01:
; ---- the fundamental's index and the decay index -------------------------
; PITCH and DECAY are decoded exactly as every other renderer's are (the
; machine's packed base, plus a +-16 trim), but this engine needs the INDEX
; rather than the coefficient: a frequency RATIO is a fixed offset along an
; exponential curve, so a partial at 3x the fundamental is "32 steps up the
; band table" and costs an add. y1 still holds the packed word, and it stays
; live through the whole decode -- zr08 and zr09 do not touch it.
        move y1,a
        asr #$e,a,a
        and #>$7f,a             ; the band field
        move a1,x1
        move x:(r6+$0),a
        bsr zr09
        move x1,b
        add b,a
        move a1,x0
        move x0,x:(r5+@RS1@)
        move y1,a
        asr #$7,a,a
        and #>$7f,a             ; the decay field
        move a1,x1
        move x:(r6+$1),a
        bsr zr09
        move x1,b
        add b,a
        move a1,x0
        move x0,x:(r5+@RS2@)
; ⚠️ THE AMPLITUDE ENVELOPE IS A GUARD, NOT THE DECAY. The pole radius is the
; decay here, so an envelope at the DECAY knob's own rate would halve every
; ring. This one is the same table word shifted @GRDSH@ instead of @DECSH@ --
; exactly twice the longest partial's own fall, where the first version used a
; fixed 24-step index offset (2.6x) and cut the tail audibly. It is still the
; thing that guarantees the voice reaches zero: a 24-bit resonator at
; r = 0.9999 can hold a one-LSB limit cycle indefinitely, and "I took away the
; trig and it kept ringing until I stopped the octa" is a report this family
; has already had once, from a different cause. bdnoise.py's tail gate holds
; it.
        move x:(r5+@RS2@),a
        bsr zr08
        move #>@N_DE@,r1
        move x:(r1+n1),x0
        move x0,a
        asr #@GRDSH@,a,a
        move a1,x0
        move x0,x:(r5+@DE@)
; BRITE (knob 3): the exciter's one-pole corner, from the frequency curve. A
; dull strike excites the low partials only; a bright one feeds all six.
; ⚠️ OFFSET @BRTOFF@ INDEX STEPS UP, SO 64 IS BRIGHT. Read straight, knob 64
; puts the corner at 1.8 kHz -- and a one-pole rolls off 6 dB an octave, so the
; sixth partial at 5.9 kHz arrives 10 dB down and the FUNDAMENTAL WINS AGAIN,
; even with the resonator gains equalised. That was the second half of "it just
; sounds like a bass drum" and it is not visible in any per-partial
; measurement: every partial is where it should be, at the amplitude its own
; weight asks for, and the thing deciding the balance is upstream of all of
; them. 64 now lands near 7 kHz, which feeds all six; the knob still reaches
; 1 kHz at the bottom for a dull, wooden strike.
        move x:(r6+$3),a
        add #>@BRTOFF@,a
        bsr zr08
        move #>@N_F@,r1
        move x:(r1+n1),x0
        move x0,x:(r5+@RXC@)
; ---- partial 1: the fundamental -----------------------------------------
; Each partial is: its own decay index into x1, its own band index into a,
; then zr10 for the coefficient pair, then its POS weight. The per-partial
; constants are RSH (where the harmonic series puts it), RSD (how much further
; a bar's modes put it) and RSC (how much sooner it dies).
        move x:(r5+@RS2@),a
        move a1,x1
        move x:(r5+@RS1@),a
        bsr zr10
        move y0,x:(r5+@RA1@)
        move y1,x:(r5+@RA2@)
        move x:(r6+$4),a
        asl #$10,a,a            ; POS as knob/128
        move a1,x0
        move #>@RDG0@,y0
        mpy y0,x0,a
        move #>@RGL0@,x0
        move x0,b
        add b,a                 ; a = the POS weight
        move a,x0
        move x1,y0              ; x sin(theta): cancels the resonator's own
        mpy y0,x0,a             ;   1/sin(w) gain, so the partials come out
        asl a                   ;   level instead of fundamental-heavy
        asl a
        move a,x0
        move x0,x:(r5+@RG1@)
; ---- partial 2 -----------------------------------------------------------
        move x:(r5+@RS2@),a
        sub #>@RSC1@,a
        move a1,x1
        bsr zr11
        move #>@RSD1@,x0
        mpy y0,x0,a
        asr #$10,a,a            ; (struc * RSD) / 128, an integer
        move a1,x0
        move x0,a               ; drop the shifted-out remainder from a0
        move #>@RSH1@,x0
        move x0,b
        add b,a
        move x:(r5+@RS1@),x0
        move x0,b
        add b,a
        bsr zr10
        move y0,x:(r5+@RA3@)
        move y1,x:(r5+@RA4@)
        move x:(r6+$4),a
        asl #$10,a,a
        move a1,x0
        move #>@RDG1@,y0
        mpy y0,x0,a
        move #>@RGL1@,x0
        move x0,b
        add b,a                 ; a = the POS weight
        move a,x0
        move x1,y0              ; x sin(theta): cancels the resonator's own
        mpy y0,x0,a             ;   1/sin(w) gain, so the partials come out
        asl a                   ;   level instead of fundamental-heavy
        asl a
        move a,x0
        move x0,x:(r5+@RG2@)
; ---- partial 3 -----------------------------------------------------------
        move x:(r5+@RS2@),a
        sub #>@RSC2@,a
        move a1,x1
        bsr zr11
        move #>@RSD2@,x0
        mpy y0,x0,a
        asr #$10,a,a
        move a1,x0
        move x0,a
        move #>@RSH2@,x0
        move x0,b
        add b,a
        move x:(r5+@RS1@),x0
        move x0,b
        add b,a
        bsr zr10
        move y0,x:(r5+@RA5@)
        move y1,x:(r5+@RA6@)
        move x:(r6+$4),a
        asl #$10,a,a
        move a1,x0
        move #>@RDG2@,y0
        mpy y0,x0,a
        move #>@RGL2@,x0
        move x0,b
        add b,a                 ; a = the POS weight
        move a,x0
        move x1,y0              ; x sin(theta): cancels the resonator's own
        mpy y0,x0,a             ;   1/sin(w) gain, so the partials come out
        asl a                   ;   level instead of fundamental-heavy
        asl a
        move a,x0
        move x0,x:(r5+@RG3@)
; ---- partial 4 -----------------------------------------------------------
        move x:(r5+@RS2@),a
        sub #>@RSC3@,a
        move a1,x1
        bsr zr11
        move #>@RSD3@,x0
        mpy y0,x0,a
        asr #$10,a,a
        move a1,x0
        move x0,a
        move #>@RSH3@,x0
        move x0,b
        add b,a
        move x:(r5+@RS1@),x0
        move x0,b
        add b,a
        bsr zr10
        move y0,x:(r5+@RA7@)
        move y1,x:(r5+@RA8@)
        move x:(r6+$4),a
        asl #$10,a,a
        move a1,x0
        move #>@RDG3@,y0
        mpy y0,x0,a
        move #>@RGL3@,x0
        move x0,b
        add b,a                 ; a = the POS weight
        move a,x0
        move x1,y0              ; x sin(theta): cancels the resonator's own
        mpy y0,x0,a             ;   1/sin(w) gain, so the partials come out
        asl a                   ;   level instead of fundamental-heavy
        asl a
        move a,x0
        move x0,x:(r5+@RG4@)
; ---- partial 5 -----------------------------------------------------------
        move x:(r5+@RS2@),a
        sub #>@RSC4@,a
        move a1,x1
        bsr zr11
        move #>@RSD4@,x0
        mpy y0,x0,a
        asr #$10,a,a
        move a1,x0
        move x0,a
        move #>@RSH4@,x0
        move x0,b
        add b,a
        move x:(r5+@RS1@),x0
        move x0,b
        add b,a
        bsr zr10
        move y0,x:(r5+@RA9@)
        move y1,x:(r5+@RA10@)
        move x:(r6+$4),a
        asl #$10,a,a
        move a1,x0
        move #>@RDG4@,y0
        mpy y0,x0,a
        move #>@RGL4@,x0
        move x0,b
        add b,a                 ; a = the POS weight
        move a,x0
        move x1,y0              ; x sin(theta): cancels the resonator's own
        mpy y0,x0,a             ;   1/sin(w) gain, so the partials come out
        asl a                   ;   level instead of fundamental-heavy
        asl a
        move a,x0
        move x0,x:(r5+@RG5@)
; ---- partial 6 -----------------------------------------------------------
        move x:(r5+@RS2@),a
        sub #>@RSC5@,a
        move a1,x1
        bsr zr11
        move #>@RSD5@,x0
        mpy y0,x0,a
        asr #$10,a,a
        move a1,x0
        move x0,a
        move #>@RSH5@,x0
        move x0,b
        add b,a
        move x:(r5+@RS1@),x0
        move x0,b
        add b,a
        bsr zr10
        move y0,x:(r5+@RA11@)
        move y1,x:(r5+@RA12@)
        move x:(r6+$4),a
        asl #$10,a,a
        move a1,x0
        move #>@RDG5@,y0
        mpy y0,x0,a
        move #>@RGL5@,x0
        move x0,b
        add b,a                 ; a = the POS weight
        move a,x0
        move x1,y0              ; x sin(theta): cancels the resonator's own
        mpy y0,x0,a             ;   1/sin(w) gain, so the partials come out
        asl a                   ;   level instead of fundamental-heavy
        asl a
        move a,x0
        move x0,x:(r5+@RG6@)
; the trig convention is the 808's: knob $c is the frame offset, or negative
        move x:(r6+$c),a
        tst a
        blt zr03
        move a,x:(r5+@SEG@)
        bsr zr04
        bsr zr06
        move n7,a
        move x:(r5+@SEG@),x0
        sub x0,a
        bsr zr04
        rts
zr03:
        move n7,a
        bsr zr04
        rts
; --- zr04: render `a` samples --------------------------------------------
zr04:
        tst a
        beq zr05
        do a,zr07
; ---- the exciter: noise, a one-pole, and a 2 ms envelope ----------------
; The family's LCG, idiom for idiom.
        move x:(r5+@LCG@),x0
        move #>@LCGK@,y0
        mpy y0,x0,b             #0,x1
        add x,b                 #>@LCGC@,y0
        move #0,y1
        add y,b
        move b0,x0
        move x0,x:(r5+@LCG@)
; xl += c*(noise - xl)
        move x:(r5+@RXL@),y0
        move x0,b
        sub y0,b
        move b,x0
        move x:(r5+@RXC@),y0
        mpy y0,x0,a
        move x:(r5+@RXL@),b
        add a,b
        move b,x:(r5+@RXL@)
; times its own envelope -> x1, the strike every resonator sees this sample
; ⚠️ AND THE ENVELOPE STARTS AT @RXHIT@, NOT AT 1.0. A two-pole resonator's
; impulse response is about 1/sin(w) times its input -- thirteen times, at the
; 563 Hz this machine's base asks for -- and a noise burst goes on exciting it
; for every sample it lasts. At full scale the bank clips on its own strike.
        move b,x0
        move x:(r5+@RXE@),y0
        mpy y0,x0,a
        move a,x1
        move x:(r5+@RXE@),b
        move b,x0
        move #>@RXDE@,y0
        mpy y0,x0,a
        sub a,b
        move b,x:(r5+@RXE@)
; ---- resonator 1 --------------------------------------------------------
; ⚠️ a1 AND a2 ARE BOTH STORED HALVED AND THE SUM IS DOUBLED ONCE. a1 = 2r*cos
; reaches 2, which does not fit Q23 -- the family's own halved-coefficient
; convention, except that here it buys something extra: two terms at the same
; scale can share ONE `asl`, where doubling each product would cost two.
; The state store is `move a,x:(...)`, which LIMITS. That is deliberate: it is
; the only thing standing between a resonator driven too hard and a number
; that wraps from +full to -full, which is an explosion rather than a clip.
; y1 carries the sum across the six; x1 is the strike.
;
; ⚠️ THE PER-PARTIAL WEIGHT IS APPLIED TO THE STRIKE, NOT TO THE OUTPUT, AND
; THE DIFFERENCE IS HEADROOM. A resonator is linear, so the two give the same
; sound -- but weighted on the OUTPUT, the low partials RING at
; strike x 1/sin(w), which is 12x the strike at 563 Hz. Their state saturates
; while the weighted output is still a tenth of full scale, so the engine
; compresses its own attack and can never get loud: measured 0.064 peak at a
; 0.05 strike and 0.192 at 0.4 -- a 2.7x input for a 1.5x output, with nothing
; in the signal path that looks like a compressor. Weighted on the way in,
; every partial rings at about the same amplitude, nothing saturates, and the
; output is the honest sum of six.
        move x:(r5+@RY2@),x0
        move x:(r5+@RA2@),y0
        mpy y0,x0,a             ; (a2/2)*y[n-2]
        move x:(r5+@RY1@),x0
        move x:(r5+@RA1@),y0
        mpy y0,x0,b             ; (a1/2)*y[n-1]
        add b,a
        asl a
        move x1,x0              ; the strike, weighted on the WAY IN
        move x:(r5+@RG1@),y0
        mpy y0,x0,b
        add b,a
        move x:(r5+@RY1@),x0
        move x0,x:(r5+@RY2@)
        move a,x:(r5+@RY1@)
        move a,y1               ; y1 starts the sum
; ---- resonator 2 --------------------------------------------------------
        move x:(r5+@RY4@),x0
        move x:(r5+@RA4@),y0
        mpy y0,x0,a
        move x:(r5+@RY3@),x0
        move x:(r5+@RA3@),y0
        mpy y0,x0,b
        add b,a
        asl a
        move x1,x0              ; the strike, weighted on the WAY IN
        move x:(r5+@RG2@),y0
        mpy y0,x0,b
        add b,a
        move x:(r5+@RY3@),x0
        move x0,x:(r5+@RY4@)
        move a,x:(r5+@RY3@)
        move y1,b
        add b,a
        move a,y1
; ---- resonator 3 --------------------------------------------------------
        move x:(r5+@RY6@),x0
        move x:(r5+@RA6@),y0
        mpy y0,x0,a
        move x:(r5+@RY5@),x0
        move x:(r5+@RA5@),y0
        mpy y0,x0,b
        add b,a
        asl a
        move x1,x0              ; the strike, weighted on the WAY IN
        move x:(r5+@RG3@),y0
        mpy y0,x0,b
        add b,a
        move x:(r5+@RY5@),x0
        move x0,x:(r5+@RY6@)
        move a,x:(r5+@RY5@)
        move y1,b
        add b,a
        move a,y1
; ---- resonator 4 --------------------------------------------------------
        move x:(r5+@RY8@),x0
        move x:(r5+@RA8@),y0
        mpy y0,x0,a
        move x:(r5+@RY7@),x0
        move x:(r5+@RA7@),y0
        mpy y0,x0,b
        add b,a
        asl a
        move x1,x0              ; the strike, weighted on the WAY IN
        move x:(r5+@RG4@),y0
        mpy y0,x0,b
        add b,a
        move x:(r5+@RY7@),x0
        move x0,x:(r5+@RY8@)
        move a,x:(r5+@RY7@)
        move y1,b
        add b,a
        move a,y1
; ---- resonator 5 --------------------------------------------------------
        move x:(r5+@RY10@),x0
        move x:(r5+@RA10@),y0
        mpy y0,x0,a
        move x:(r5+@RY9@),x0
        move x:(r5+@RA9@),y0
        mpy y0,x0,b
        add b,a
        asl a
        move x1,x0              ; the strike, weighted on the WAY IN
        move x:(r5+@RG5@),y0
        mpy y0,x0,b
        add b,a
        move x:(r5+@RY9@),x0
        move x0,x:(r5+@RY10@)
        move a,x:(r5+@RY9@)
        move y1,b
        add b,a
        move a,y1
; ---- resonator 6 --------------------------------------------------------
        move x:(r5+@RY12@),x0
        move x:(r5+@RA12@),y0
        mpy y0,x0,a
        move x:(r5+@RY11@),x0
        move x:(r5+@RA11@),y0
        mpy y0,x0,b
        add b,a
        asl a
        move x1,x0              ; the strike, weighted on the WAY IN
        move x:(r5+@RG6@),y0
        mpy y0,x0,b
        add b,a
        move x:(r5+@RY11@),x0
        move x0,x:(r5+@RY12@)
        move a,x:(r5+@RY11@)
        move y1,b
        add b,a
        move a,y1
; ---- the guard envelope, and out ----------------------------------------
        move x:(r5+@ENV@),b
        move b,x0
        move x:(r5+@DE@),y0
        mpy y0,x0,a
        sub a,b
        move b,x:(r5+@ENV@)
        move b,y0
        move y1,x0
        mpy y0,x0,a
        move a,x0
        move x:(r5+@GAIN@),y0
        mpy y0,x0,a
        asl a                   ; DRIVE (knob 5)
        asl a
        asl a
        move a,x:(r0)+
        move a,x:(r0)+
zr07:
zr05:
        rts
; --- zr06: the trig -------------------------------------------------------
; ⚠️ TWELVE RESONATOR WORDS AND THE EXCITER'S POLE, ALL OF THEM. These are the
; 909's slots; a track that was a kick hands this engine twelve words of a
; filter mid-swing, and a two-pole resonator started from a large state rings
; at full scale from sample zero -- with no strike to blame and no knob that
; changes it. The exciter's one-pole state matters as much: left stale it is a
; DC step into six resonators, which is exactly the "a persistent slot init
; does not clear" trap in the only form that is audible here.
zr06:
        clr a
        move a,x:(r5+@RY1@)
        move a,x:(r5+@RY2@)
        move a,x:(r5+@RY3@)
        move a,x:(r5+@RY4@)
        move a,x:(r5+@RY5@)
        move a,x:(r5+@RY6@)
        move a,x:(r5+@RY7@)
        move a,x:(r5+@RY8@)
        move a,x:(r5+@RY9@)
        move a,x:(r5+@RY10@)
        move a,x:(r5+@RY11@)
        move a,x:(r5+@RY12@)
        move a,x:(r5+@RXL@)
        move #>@RXHIT@,a
        move a,x:(r5+@RXE@)
        move #>$7fffff,a
        move a,x:(r5+@ENV@)
        rts
; --- zr11: the STRUCTURE blend's multiplier -------------------------------
; Out: y0 = the STRUC knob as knob/128 in Q23, for the (struc * RSD) / 128
; the callers above do. One instruction fewer than parking it in a slot, and
; the voice block has no slot left to park it in -- 48 of 48 are state.
zr11:
        move x:(r6+$2),a
        asl #$10,a,a
        move a1,y0
        rts
; --- zr10: one partial's coefficient pair ---------------------------------
; In:  a  = the partial's band index (unclamped), x1 = its decay index.
; Out: y0 = a1/2 = r*cos(w),  y1 = a2/2 = -(r^2)/2.
; A subroutine rather than six copies: it runs once per block per track and
; thirty words times six is a hundred and fifty of the ground for nothing.
; ⚠️ AND IT RETURNS sin(theta) AS WELL, WHICH IS THE WHOLE FIX FOR "IT SOUNDS
; LIKE A BASS DRUM". A two-pole resonator's impulse response is about 1/sin(w)
; times its input, so at a 563 Hz fundamental and a 5.9 kHz sixth partial the
; SAME excitation and the SAME weight come out 9x apart -- the bank is a
; fundamental with five whispers behind it, whatever the weights say. There is
; nothing to measure that would show this: every partial lands on its own
; frequency and decays for its own length, which is all the gates ask. The
; caller multiplies each weight by this sine, which cancels the 1/sin(w)
; exactly, and the six partials come out level.
;
; Decay first, band second, so the decay index in x1 is consumed before
; sin(theta) takes its place. zr08 clobbers x0, y0, a, b, n1 and r1; x1 and y1
; are the only registers that survive it, which is what sets this order.
zr10:
        move a,y1               ; park the band index
        move x1,a
        bsr zr08
        move #>@N_DE@,r1
        move x:(r1+n1),x0
        move x0,a
        asr #@DECSH@,a,a        ; the ring is FOUR TIMES the curve's own fall
        move a1,x0
        move #>$7fffff,b
        move x0,y0
        sub y0,b                ; b = r = 1 - de/4
        move b,x1               ; park r: it has to survive the next zr08
        move y1,a               ; the band index back
        bsr zr08
        move #>@N_F@,r1
        move x:(r1+n1),x0       ; x0 = sin(theta)
        move x0,y1              ; park it: this is the level trim
        move x0,y0
        mpy y0,x0,a             ; sin^2(theta)
        asl a
        move #>$7fffff,b
        sub a,b                 ; b = cos(w) = 1 - 2 sin^2
        move b,x0
        move x1,y0              ; y0 = r
        mpy y0,x0,a             ; r*cos(w) = a1/2
        tfr a,b                 ; park a1/2 in b
        move x1,x0              ; x0 = r, y0 still r
        mpy y0,x0,a             ; r^2
        asr #$1,a,a
        neg a                   ; a = -(r^2)/2 = a2/2
        move y1,x1              ; x1 = sin(theta), for the caller's weight
        move a,y1               ; y1 = a2/2
        move b,y0               ; y0 = a1/2
        rts
; --- zr08, zr09: bdnoise.asm's clamp and trim, again ----------------------
; ⚠️ COPIED, AND NOT BY CHOICE. `dsp_asm` resolves `bsr` and `bra` to a label
; FORWARD ONLY -- a backward one is InvalidInstruction, whatever the distance
; (probed: even -6 words), and `jsr`/`jmp` take a 12-bit absolute where this
; engine lands around P:0x1400. bdnoise.asm's zn08/zn09 sit 800 words above
; this file in the concatenated source, so there is no form that reaches them.
; Thirty words of duplication is the price; the alternative was putting the
; ring engine FIRST, which only moves the problem to the dispatch chain.
; They are character-for-character bdnoise.asm's, including why each line is
; the way it is -- read the originals for that.
zr09:
        sub #>$40,a
        asr #$2,a,a
        move a1,x0
        move x0,a
        rts
zr08:
        move #$0,x0
        tst a
        tmi x0,a
        tfr a,b
        move #>$7f,a
        move #>$7f,x0
        sub b,a
        tmi x0,b
        tfr b,a
        move a1,y0
        asr #$1,a,a
        move a1,n1
        rts
